// Generic service worker. It knows nothing about units, banks or languages.
//
// - shell-<version>: the app shell listed in sw-config.js (generated by generate-registry.ps1). A new release gets a
//   new version, so its cache is built from scratch and the old shell-* caches are deleted on activate.
// - media: audio files. It survives releases; it is filled by the page through the `cache-urls` message and read here.
// - fonts: Google Fonts CSS and font files, cached on first use so the HUD looks right offline.
importScripts('sw-config.js');

const SHELL_CACHE = `shell-${self.SW_CONFIG.version}`;
const MEDIA_CACHE = 'media';
const FONT_CACHE = 'fonts';
const FONT_HOSTS = ['fonts.googleapis.com', 'fonts.gstatic.com'];
const AUDIO_PATTERN = /\.(ogg|mp3|wav)$/i;
const PACK_DOWNLOAD_CONCURRENCY = 4;

self.addEventListener('install', event => {
    event.waitUntil((async () => {
        const cache = await caches.open(SHELL_CACHE);
        // `cache: 'reload'` skips the HTTP cache, so a new version never precaches stale files from the previous release.
        await Promise.all(self.SW_CONFIG.shell.map(async url => {
            const response = await fetch(new Request(url, { cache: 'reload' }));
            if (!response.ok) throw new Error(`Precache failed for ${url}: ${response.status}`);
            await cache.put(url, response);
        }));
        await self.skipWaiting();
    })());
});

self.addEventListener('activate', event => {
    event.waitUntil((async () => {
        const names = await caches.keys();
        await Promise.all(names
            .filter(name => name.startsWith('shell-') && name !== SHELL_CACHE)
            .map(name => caches.delete(name)));
        await self.clients.claim();
    })());
});

self.addEventListener('fetch', event => {
    const request = event.request;
    if (request.method !== 'GET') return;
    const url = new URL(request.url);

    if (FONT_HOSTS.includes(url.hostname)) {
        event.respondWith(handleFont(request));
        return;
    }
    if (url.origin !== self.location.origin) return;

    if (AUDIO_PATTERN.test(url.pathname)) {
        event.respondWith(handleMedia(request));
        return;
    }
    event.respondWith(handleShell(request));
});

// Shell: cache first. The query string (`?v=` cache-busting tokens) is ignored because the whole cache is versioned.
async function handleShell(request) {
    const cache = await caches.open(SHELL_CACHE);
    const cached = await cache.match(request, { ignoreSearch: true })
        || (request.mode === 'navigate' ? await cache.match('index.html') : null);
    return cached || fetch(request);
}

// Fonts: cache first, filled on first online use (cross-origin responses are opaque, which is fine for CSS and fonts).
async function handleFont(request) {
    const cache = await caches.open(FONT_CACHE);
    const cached = await cache.match(request);
    if (cached) return cached;
    const response = await fetch(request);
    if (response.ok || response.type === 'opaque') cache.put(request, response.clone());
    return response;
}

// Media: served from the media cache when present, otherwise straight from the network (not stored here: only
// the explicit pack download fills the cache). Media elements ask for byte ranges (Safari requires 206 answers),
// so cached files are sliced to the requested range.
async function handleMedia(request) {
    const cache = await caches.open(MEDIA_CACHE);
    const cached = await cache.match(request.url);
    if (!cached) return fetch(request);
    const range = request.headers.get('range');
    return range ? buildRangeResponse(cached, range) : cached;
}

async function buildRangeResponse(response, rangeHeader) {
    const blob = await response.clone().blob();
    const size = blob.size;
    const match = /^bytes=(\d*)-(\d*)$/.exec(rangeHeader.trim());
    if (!match || (match[1] === '' && match[2] === '')) return response;

    let start;
    let end;
    if (match[1] === '') {
        start = Math.max(size - Number(match[2]), 0); // suffix range: the last N bytes
        end = size - 1;
    } else {
        start = Number(match[1]);
        end = match[2] === '' ? size - 1 : Math.min(Number(match[2]), size - 1);
    }
    if (start >= size || start > end) {
        return new Response(null, { status: 416, headers: { 'Content-Range': `bytes */${size}` } });
    }
    return new Response(blob.slice(start, end + 1), {
        status: 206,
        statusText: 'Partial Content',
        headers: {
            'Content-Type': response.headers.get('Content-Type') || 'audio/ogg',
            'Content-Length': String(end - start + 1),
            'Content-Range': `bytes ${start}-${end}/${size}`
        }
    });
}

/* Messages from the page:
   { type: 'cache-urls', urls: [...] }  download missing URLs into the media cache, answers with progress messages
   { type: 'remove-urls', urls: [...] } delete URLs from the media cache (orphans)
   { type: 'list-media' }               answers { type: 'media-list', urls: [...] }
   { type: 'clear-media' }              empty the media cache */
self.addEventListener('message', event => {
    const message = event.data || {};
    const reply = payload => event.source && event.source.postMessage(payload);

    if (message.type === 'cache-urls') event.waitUntil(cacheUrls(message.urls || [], reply));
    else if (message.type === 'remove-urls') event.waitUntil(removeUrls(message.urls || []));
    else if (message.type === 'list-media') event.waitUntil(listMedia(reply));
    else if (message.type === 'clear-media') event.waitUntil(caches.delete(MEDIA_CACHE));
});

async function cacheUrls(urls, reply) {
    const cache = await caches.open(MEDIA_CACHE);
    const queue = [...new Set(urls.map(toAbsoluteUrl))];
    const total = queue.length;
    let done = 0;
    let failed = 0;

    const worker = async () => {
        while (queue.length > 0) {
            const url = queue.shift();
            try {
                if (!(await cache.match(url))) {
                    const response = await fetch(url);
                    if (!response.ok) throw new Error(String(response.status));
                    await cache.put(url, response);
                }
            } catch (error) {
                failed += 1;
            }
            done += 1;
            reply({ type: 'cache-progress', done, total, failed });
        }
    };
    await Promise.all(Array.from({ length: PACK_DOWNLOAD_CONCURRENCY }, worker));
    reply({ type: 'cache-done', total, failed });
}

async function removeUrls(urls) {
    const cache = await caches.open(MEDIA_CACHE);
    await Promise.all(urls.map(url => cache.delete(toAbsoluteUrl(url))));
}

async function listMedia(reply) {
    const cache = await caches.open(MEDIA_CACHE);
    const requests = await cache.keys();
    reply({ type: 'media-list', urls: requests.map(request => request.url) });
}

function toAbsoluteUrl(url) {
    return new URL(url, self.registration.scope).href;
}
